288	    /// Build the progress steps line for the header center.
289	    fn build_progress_line(&self) -> Line<'static> {
290	        let labels: Vec<String> = ProgressStep::all()
291	            .iter()
292	            .map(|s| s.label().into())
293	            .collect();
294	        let progress = ProgressSteps::new(labels, self.current_step.index());
295	        progress.to_line()
296	    }
