298	    fn render_header(&self, frame: &mut Frame, area: Rect, hits: &mut HitMap) {
299	        if area.height == 0 || area.width == 0 {
300	            return;
301	        }
302	
303	        let header_data = HeaderData::new(&self.project_name, None::<&str>).with_subtitle("init");
304	
305	        let progress_line = self.build_progress_line();
306	
307	        let cancel_btn = Button::new("Cancel").color(ButtonColor::Muted);
308	        let confirm_btn = Button::new("Confirm & Run")
309	            .icon("⏎")
310	            .color(ButtonColor::Accent);
311	
312	        let widget = HeaderWidget::new(&header_data, &self.theme)
313	            .center(progress_line)
314	            .actions(vec![cancel_btn, confirm_btn]);
315	
316	        let button_rects = widget.render_to_frame(frame, area);
317	
318	        // Register hit regions for action buttons
319	        if let Some(cancel_rect) = button_rects.first() {
320	            hits.register(HitRegion {
321	                area: *cancel_rect,
322	                action: Action::Cancel,
323	                index: None,
324	                click: ClickBehavior::Fire,
325	            });
326	        }
327	        if let Some(confirm_rect) = button_rects.get(1) {
328	            hits.register(HitRegion {
329	                area: *confirm_rect,
330	                action: Action::Confirm,
331	                index: None,
332	                click: ClickBehavior::Fire,
333	            });
334	        }
