337	    fn render_help_overlay(&self, frame: &mut Frame, area: Rect) {
338	        let bindings = self.bindings();
339	        let footer = bindings.footer_bindings();
340	
341	        // Build help lines
342	        let mut lines: Vec<Line> = Vec::new();
343	        lines.push(Line::default()); // blank line after title
344	        for binding in &footer {
345	            lines.push(Line::from(vec![
346	                Span::styled(
347	                    format!("{:<12}", binding.key_label),
348	                    Style::default()
349	                        .fg(Palette::LIME)
350	                        .add_modifier(Modifier::BOLD),
351	                ),
352	                Span::styled(binding.description, Style::default().fg(Palette::TEXT)),
353	            ]));
354	        }
355	        lines.push(Line::default()); // blank line before close hint
356	        lines.push(Line::styled(
357	            "Press any key to close",
358	            Style::default().fg(Palette::TEXT_DIM),
359	        ));
360	
361	        let content_height = lines.len() as u16 + 2; // +2 for border
362	        let content_width = 36u16;
363	
364	        let overlay_width = content_width.min(area.width.saturating_sub(4));
365	        let overlay_height = content_height.min(area.height.saturating_sub(2));
366	
367	        let x = area.x + (area.width.saturating_sub(overlay_width)) / 2;
368	        let y = area.y + (area.height.saturating_sub(overlay_height)) / 2;
369	
370	        let overlay_area = Rect::new(x, y, overlay_width, overlay_height);
371	
372	        // Clear background
373	        frame.render_widget(Clear, overlay_area);
374	
375	        let block = Block::default()
376	            .borders(Borders::ALL)
377	            .border_type(ratatui::widgets::BorderType::Rounded)
378	            .border_style(Style::default().fg(Palette::LIME))
379	            .title(" Help ")
380	            .title_style(
381	                Style::default()
382	                    .fg(Palette::LIME)
383	                    .add_modifier(Modifier::BOLD),
384	            )
385	            .style(Style::default().bg(Palette::BG_ELEVATED));
386	
387	        let inner = block.inner(overlay_area);
388	        frame.render_widget(block, overlay_area);
389	
390	        // Render lines inside the block
391	        for (i, line) in lines.iter().enumerate() {
392	            let ly = inner.y + i as u16;
393	            if ly >= inner.y + inner.height {
394	                break;
395	            }
396	            frame
397	                .buffer_mut()
398	                .set_line(inner.x + 1, ly, line, inner.width.saturating_sub(2));
399	        }
400	    }
401	
402	    fn render_detections(&self, frame: &mut Frame, area: Rect, mode: DegradeMode) {
403	        let found: Vec<_> = self.detections.iter().filter(|d| d.found).collect();
404	
405	        // Create card with title — DegradeMode flows through from allocator
406	        let card = SectionCard::new().title("DETECTED").degrade_mode(mode);
407	        let inner = card.render(frame, area);
408	
409	        if inner.height == 0 {
410	            return;
411	        }
412	
413	        // Render count badge in top-right of card (only when Full mode has a border)
414	        if mode == DegradeMode::Full && inner.height > 0 {
415	            let count = format!("{} items", found.len());
416	            let badge_x = inner.x + inner.width - count.len() as u16 - 1;
417	            frame.buffer_mut().set_string(
418	                badge_x,
419	                area.y, // In the border row
420	                &count,
421	                Style::default().fg(Palette::TEAL),
422	            );
423	        }
424	
425	        if found.is_empty() {
426	            let empty = Line::styled(
427	                "No technologies detected",
428	                Style::default().fg(Palette::TEXT_DIM),
429	            );
430	            frame
431	                .buffer_mut()
432	                .set_line(inner.x, inner.y, &empty, inner.width);
433	            return;
434	        }
435	
436	        // Create chip group items
437	        let chip_items: Vec<ChipGroupItem> = found
438	            .iter()
439	            .map(|d| ChipGroupItem::new(&d.name, d.detail.as_deref()))
440	            .collect();
441	
442	        let chip_group = ChipGroup::new(chip_items).degrade_mode(mode);
443	        chip_group.render(frame, inner);
444	
445	        // Render "Based on:" line if we have space
446	        if inner.height >= 4 {
447	            let details: Vec<_> = found.iter().filter_map(|d| d.detail.as_deref()).collect();
448	
449	            if !details.is_empty() {
450	                let based_on = format!("Based on: {}", details.join(", "));
451	                let y = inner.y + inner.height - 1;
452	
453	                // Draw subtle separator
454	                for x in inner.x..inner.x + inner.width {
455	                    if let Some(cell) = frame
456	                        .buffer_mut()
457	                        .cell_mut(Position::new(x, y.saturating_sub(1)))
458	                    {
459	                        cell.set_style(Style::default().fg(Palette::BORDER_SUBTLE));
460	                    }
461	                }
462	
463	                frame.buffer_mut().set_string(
464	                    inner.x,
465	                    y,
466	                    &based_on,
467	                    Style::default().fg(Palette::TEXT_DIM),
468	                );
469	            }
470	        }
471	    }
472	
473	    fn render_step_templates(
474	        &self,
475	        frame: &mut Frame,
476	        area: Rect,
477	        hits: &mut HitMap,
478	        mode: DegradeMode,
479	    ) {
480	        // Create card — DegradeMode flows through from allocator
481	        let card = SectionCard::new()
482	            .title("Add templates?")
483	            .degrade_mode(mode);
484	        let inner = card.render(frame, area);
485	
486	        if inner.height == 0 || self.step_templates.is_empty() {
487	            return;
488	        }
489	
490	        // Only show helper text in Full mode — Compact/Minimal need all space for the list
491	        let mut y = inner.y;
492	        let mut lines_used = 0u16;
493	
494	        if mode == DegradeMode::Full {
495	            let helper_text = "Bivvy has templates available for commonly used package managers \
496	                               and tools found in your project to help you get started quickly. \
497	                               Select any you'd like to include. Leave out the ones you don't.";
498	
499	            let helper_style = Style::default().fg(Palette::TEXT_DIM);
500	            let max_width = inner.width as usize;
501	            let words: Vec<&str> = helper_text.split_whitespace().collect();
502	            let mut current_line = String::new();
503	
504	            for word in words {
505	                let test_line = if current_line.is_empty() {
506	                    word.to_string()
507	                } else {
508	                    format!("{} {}", current_line, word)
509	                };
510	
511	                if test_line.len() <= max_width {
512	                    current_line = test_line;
513	                } else {
514	                    if y < inner.y + inner.height {
515	                        frame
516	                            .buffer_mut()
517	                            .set_string(inner.x, y, &current_line, helper_style);
518	                        y += 1;
519	                        lines_used += 1;
520	                    }
521	                    current_line = word.to_string();
522	                }
523	            }
524	            if !current_line.is_empty() && y < inner.y + inner.height {
525	                frame
526	                    .buffer_mut()
527	                    .set_string(inner.x, y, &current_line, helper_style);
528	                y += 1;
529	                lines_used += 1;
530	            }
531	
532	            // Spacing after helper text
533	            y += 1;
534	        }
535	
536	        // Calculate remaining area for card list
537	        let spacing_offset = if mode == DegradeMode::Full {
538	            lines_used + 2
539	        } else {
540	            0
541	        };
542	        let list_area = Rect {
543	            x: inner.x,
544	            y,
545	            width: inner.width,
546	            height: inner.height.saturating_sub(spacing_offset),
547	        };
548	
549	        if list_area.height == 0 {
550	            return;
551	        }
552	
553	        // Build card list items (multi-select behavior is in toggle_selection)
554	        let items: Vec<CardListItem> = self
555	            .step_templates
556	            .iter()
557	            .enumerate()
558	            .map(|(i, t)| {
559	                CardListItem::new(&t.name, &t.reason, t.selected, i == self.selected_index)
560	            })
561	            .collect();
562	
563	        let card_list = CardList::new(items)
564	            .spacing(CardListSpacing::Compact)
565	            .scroll_offset(self.scroll_offset);
566	
567	        // Update visible_count for scrolling calculations
568	        let visible = card_list.items_that_fit(list_area.height);
569	        self.visible_count.set(visible);
570	
571	        card_list.render(frame, list_area);
572	
573	        // Register hit regions for each visible step template item.
574	        // CardList default card_height is 4; compact spacing has gap 0.
575	        let card_height = 4u16;
576	        let gap = CardListSpacing::Compact.gap();
577	        let start = self.scroll_offset;
578	        let end = (start + visible).min(self.step_templates.len());
579	        let mut item_y = list_area.y;
580	        for i in start..end {
581	            let item_rect = Rect::new(list_area.x, item_y, list_area.width, card_height);
582	            hits.register(HitRegion {
583	                area: item_rect,
584	                action: Action::Toggle,
585	                index: Some(i),
586	                click: ClickBehavior::FocusThenFire,
587	            });
588	            item_y += card_height + gap;
589	        }
590	    }
591	
592	    fn render_summary(&self, frame: &mut Frame, area: Rect, mode: DegradeMode) {
593	        let card = SectionCard::new().title("SUMMARY").degrade_mode(mode);
594	        let inner = card.render(frame, area);
595	
596	        if inner.height == 0 {
597	            return;
598	        }
599	
600	        let selected_steps = self.get_selected_steps();
601	        let step_count = selected_steps.len();
602	        let total_count = self.step_templates.len();
603	
604	        // Two column grid
605	        let col_width = inner.width / 2;
606	        let y = inner.y;
607	
608	        // Column 1: Selected Steps
609	        frame.buffer_mut().set_string(
610	            inner.x,
611	            y,
612	            "Selected Steps",
613	            Style::default().fg(Palette::TEXT_DIM),
614	        );
615	        let steps_display = if step_count == 0 {
616	            "none".to_string()
617	        } else {
618	            format!("{} of {}", step_count, total_count)
619	        };
620	        frame.buffer_mut().set_string(
621	            inner.x,
622	            y + 1,
623	            &steps_display,
624	            Style::default()
625	                .fg(if step_count > 0 {
626	                    Palette::TEAL
627	                } else {
628	                    Palette::TEXT_MUTED
629	                })
630	                .add_modifier(Modifier::BOLD),
631	        );
632	
633	        // Column 2: Step names (if any selected)
634	        frame.buffer_mut().set_string(
635	            inner.x + col_width,
636	            y,
637	            "Templates",
638	            Style::default().fg(Palette::TEXT_DIM),
639	        );
640	        let names = if selected_steps.is_empty() {
641	            "—".to_string()
642	        } else {
643	            selected_steps.join(", ")
644	        };
645	        // Truncate if too long
646	        let max_len = (col_width as usize).saturating_sub(1);
647	        let names_display = if names.len() > max_len {
648	            format!("{}…", &names[..max_len.saturating_sub(1)])
649	        } else {
650	            names
651	        };
652	        frame.buffer_mut().set_string(
653	            inner.x + col_width,
654	            y + 1,
655	            &names_display,
656	            Style::default().fg(Palette::TEXT),
657	        );
658	    }
659	}
660	
661	impl Default for InitScreen {
662	    fn default() -> Self {
663	        Self::new()
664	    }
665	}
666	
667	impl Screen for InitScreen {
668	    fn render(&self, frame: &mut Frame, area: Rect, _app_state: &AppState, hits: &mut HitMap) {
669	        // Clear with main background
670	        frame
671	            .buffer_mut()
672	            .set_style(area, Style::default().bg(Palette::BG));
673	
674	        // Global padding (2 columns horizontal, 1 row vertical)
675	        let padded = Rect {
676	            x: area.x + 2,
677	            y: area.y + 1,
678	            width: area.width.saturating_sub(4),
679	            height: area.height.saturating_sub(2),
680	        };
681	
682	        // 1. Get vertical region definitions from screen_layouts
683	        let regions = screen_layouts::init();
684	
685	        // 2. Allocate heights
686	        let allocations = allocate_regions(padded.height, &regions);
687	
688	        // 3. Compute Rect + DegradeMode for each region
689	        let mut y = padded.y;
690	        let mut region_areas: Vec<(&str, Rect, DegradeMode)> = Vec::new();
691	        for alloc in &allocations {
692	            let rect = Rect::new(padded.x, y, padded.width, alloc.height);
693	            region_areas.push((alloc.name, rect, alloc.mode));
694	            y += alloc.height;
695	        }
696	
697	        // 4. Render each region, passing DegradeMode to components
698	        for &(name, rect, mode) in &region_areas {
699	            if rect.height == 0 {
700	                continue;
701	            }
702	            match name {
703	                "header" => {
704	                    self.render_header(frame, rect, hits);
705	                }
706	                "detection" => {
707	                    self.render_detections(frame, rect, mode);
708	                }
709	                "steps" => {
710	                    self.render_step_templates(frame, rect, hits, mode);
711	                }
712	                "summary" => {
713	                    self.render_summary(frame, rect, mode);
714	                }
715	                "footer" => {
716	                    let binding_set = self.bindings();
717	                    let footer_hints: Vec<KeyHint> = binding_set
718	                        .footer_bindings()
719	                        .iter()
720	                        .map(|b| KeyHint::new(b.key_label, b.description))
721	                        .collect();
722	                    let footer = FooterWidget::new(footer_hints);
723	                    footer.render(rect, frame.buffer_mut(), &self.theme);
724	                }
725	                _ => {}
726	            }
727	        }
728	
729	        // 5. Render help overlay on top of everything
730	        if self.show_help {
731	            self.render_help_overlay(frame, area);
732	        }
733	    }
734	
735	    fn bindings(&self) -> BindingSet {
736	        let mut set = BindingSet::new();
737	        set.add(bindings::NAVIGATE);
738	        set.add(bindings::TOGGLE);
739	        set.add(bindings::CONFIRM);
740	        set.add(bindings::CANCEL);
741	        set.add(bindings::QUIT);
742	        set.add(bindings::HELP);
743	        set
744	    }
745	
746	    fn handle_action(&mut self, action: Action, _state: &mut AppState) -> ScreenResult {
747	        // When help is showing, Help toggles it off; any other action dismisses it
748	        if self.show_help {
749	            self.show_help = false;
750	            return ScreenResult::Continue;
751	        }
752	
753	        match action {
754	            Action::Quit | Action::Cancel => {
755	                self.cancelled = true;
756	                ScreenResult::Quit
757	            }
758	            Action::Up => {
759	                self.move_selection(-1);
760	                ScreenResult::Continue
761	            }
762	            Action::Down => {
763	                self.move_selection(1);
764	                ScreenResult::Continue
765	            }
766	            Action::Toggle => {
767	                self.toggle_selection();
768	                ScreenResult::Continue
769	            }
770	            Action::Confirm => {
771	                self.completed = true;
772	                ScreenResult::Quit
773	            }
774	            Action::ScrollUp => {
775	                self.move_selection(-1);
776	                ScreenResult::Continue
777	            }
778	            Action::ScrollDown => {
779	                self.move_selection(1);
780	                ScreenResult::Continue
781	            }
782	            Action::Help => {
783	                self.show_help = true;
784	                ScreenResult::Continue
785	            }
786	            _ => ScreenResult::Continue,
787	        }
788	    }
789	
790	    fn handle_click(
791	        &mut self,
792	        action: Action,
793	        index: Option<usize>,
794	        click: ClickBehavior,
795	        state: &mut AppState,
796	    ) -> ScreenResult {
797	        match click {
798	            ClickBehavior::Fire => self.handle_action(action, state),
799	            ClickBehavior::FocusThenFire => {
800	                if let Some(idx) = index {
801	                    if idx == self.selected_index {
802	                        // Already focused — fire the action (toggle)
803	                        self.handle_action(action, state)
804	                    } else {
805	                        // Focus first
806	                        self.selected_index = idx;
807	                        self.ensure_visible();
808	                        ScreenResult::Continue
809	                    }
810	                } else {
811	                    ScreenResult::Continue
812	                }
813	            }
814	            ClickBehavior::FocusOnly => {
815	                if let Some(idx) = index {
816	                    self.selected_index = idx;
817	                    self.ensure_visible();
818	                }
819	                ScreenResult::Continue
820	            }
821	        }
822	    }
823	}
