225	/// RAII guard that sets the terminal to raw mode and restores on drop.
226	///
227	/// On macOS, characters that arrive while the terminal is in canonical
228	/// (cooked) mode are stored in the canonical editing buffer. When
229	/// `tcsetattr` switches to raw mode (ICANON off), macOS does NOT make
230	/// those buffered characters available for non-canonical reads — they
231	/// are effectively lost. This is a macOS kernel behavior difference
232	/// from Linux.
233	///
234	/// By setting raw mode before any prompt output, keystrokes that arrive
235	/// at any point during the prompt are always in the raw input queue and
236	/// immediately available for `read_key()`.
237	#[cfg(unix)]
238	struct RawModeGuard {
239	    fd: i32,
240	    original: libc::termios,
241	}
242	
243	#[cfg(unix)]
244	impl RawModeGuard {
245	    fn enter(term: &Term) -> std::io::Result<Self> {
246	        use std::os::unix::io::AsRawFd;
247	        let fd = term.as_raw_fd();
248	
249	        unsafe {
250	            let mut original = std::mem::MaybeUninit::<libc::termios>::uninit();
251	            if libc::tcgetattr(fd, original.as_mut_ptr()) != 0 {
252	                return Err(std::io::Error::last_os_error());
253	            }
254	            let original = original.assume_init();
255	
256	            let mut raw = original;
257	            libc::cfmakeraw(&mut raw);
258	            // Preserve output processing so \n maps to \r\n in prompt text.
259	            raw.c_oflag = original.c_oflag;
260	
261	            if libc::tcsetattr(fd, libc::TCSADRAIN, &raw) != 0 {
262	                return Err(std::io::Error::last_os_error());
263	            }
264	
265	            Ok(Self { fd, original })
266	        }
267	    }
268	}
269	
270	#[cfg(unix)]
271	impl Drop for RawModeGuard {
272	    fn drop(&mut self) {
273	        unsafe {
274	            libc::tcsetattr(self.fd, libc::TCSADRAIN, &self.original);
275	        }
276	    }
277	}
