113	        let err = BivvyError::UnknownTemplate {
114	            name: "nonexistent".into(),
115	        };
116	        assert!(err.to_string().contains("nonexistent"));
117	    }
118	
119	    #[test]
120	    fn circular_dependency_displays_cycle() {
121	        let err = BivvyError::CircularDependency {
122	            cycle: "a → b → a".into(),
123	        };
124	        assert!(err.to_string().contains("a → b → a"));
