90	    ///
91	    /// Responses are returned in order. After the queue is exhausted,
92	    /// falls back to `set_prompt_response` or defaults.
93	    pub fn queue_prompt_responses(&mut self, key: &str, responses: Vec<&str>) {
94	        let queue = responses.into_iter().map(|s| s.to_string()).collect();
95	        self.prompt_queues.insert(key.to_string(), queue);
96	    }
