        let action = prompt_recovery(&mut ui, "test", None, false, &HashSet::new(), 0).unwrap();
        assert_eq!(action, RecoveryAction::Abort);
    }

    #[test]
    fn prompt_recovery_shell() {
        let mut ui = MockUI::new();
