/// Convert dialoguer errors to BivvyError.
///
/// EOF-like errors (UnexpectedEof, broken pipe, not connected) are
/// converted to `PromptAborted` since they indicate the user pressed
/// Ctrl+D or the terminal was closed.
fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
    let io_err: std::io::Error = e.into();
    if is_terminal_unavailable(&io_err) {
        BivvyError::PromptAborted
    } else {
        BivvyError::Io(io_err)
    }
}

/// Returns true if an IO error indicates the terminal is gone or the
/// user sent EOF (Ctrl+D). These conditions all mean "no more input."
fn is_terminal_unavailable(err: &std::io::Error) -> bool {
    matches!(
        err.kind(),
        std::io::ErrorKind::UnexpectedEof
            | std::io::ErrorKind::BrokenPipe
            | std::io::ErrorKind::NotConnected
    ) || err.raw_os_error() == Some(libc::ENOTTY)
}

