+
+    #[test]
+    fn map_dialoguer_err_converts_eof_to_prompt_aborted() {
+        let eof_err = std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "eof");
+        let dialoguer_err: dialoguer::Error = eof_err.into();
+        let result = map_dialoguer_err(dialoguer_err);
+        assert!(
+            matches!(result, BivvyError::PromptAborted),
+            "Expected PromptAborted, got: {:?}",
+            result
+        );
+    }
+
+    #[test]
+    fn map_dialoguer_err_preserves_other_io_errors() {
+        let io_err = std::io::Error::new(std::io::ErrorKind::PermissionDenied, "denied");
+        let dialoguer_err: dialoguer::Error = io_err.into();
+        let result = map_dialoguer_err(dialoguer_err);
+        assert!(
+            matches!(result, BivvyError::Io(_)),
+            "Expected Io error, got: {:?}",
+            result
+        );
+    }
